class LinkCut:
    def __init__(self, values):
        n = len(values) + 1
        self.left, self.right, self.parent = ([0] * n for _ in range(3))
        self.reverse = [False] * n
        self.value = [0] + values[:]
        self.total = self.value[:]
        self.heaviest = list(range(n))

    def pull(self, x):
        left, right = self.left[x], self.right[x]
        self.total[x] = self.total[left] + self.value[x] + self.total[right]
        candidates = [x]
        if left:
            candidates.append(self.heaviest[left])
        if right:
            candidates.append(self.heaviest[right])
        self.heaviest[x] = max(candidates, key=self.value.__getitem__)

    def flip(self, x):
        if x:
            self.left[x], self.right[x] = self.right[x], self.left[x]
            self.reverse[x] = not self.reverse[x]

    def push(self, x):
        if self.reverse[x]:
            self.flip(self.left[x])
            self.flip(self.right[x])
            self.reverse[x] = False

    def aux_root(self, x):
        p = self.parent[x]
        return not p or (self.left[p] != x and self.right[p] != x)

    def rotate(self, x):
        p = self.parent[x]
        g = self.parent[p]
        if not self.aux_root(p):
            if self.left[g] == p:
                self.left[g] = x
            else:
                self.right[g] = x
        self.parent[x] = g
        if self.left[p] == x:
            middle = self.right[x]
            self.right[x], self.left[p] = p, middle
        else:
            middle = self.left[x]
            self.left[x], self.right[p] = p, middle
        self.parent[p] = x
        if middle:
            self.parent[middle] = p
        self.pull(p)
        self.pull(x)

    def splay(self, x):
        path = [x]
        while not self.aux_root(path[-1]):
            path.append(self.parent[path[-1]])
        for node in reversed(path):
            self.push(node)
        while not self.aux_root(x):
            p = self.parent[x]
            if not self.aux_root(p):
                g = self.parent[p]
                same = (self.left[g] == p) == (self.left[p] == x)
                self.rotate(p if same else x)
            self.rotate(x)

    def access(self, x):
        child, node = 0, x
        while node:
            self.splay(node)
            self.right[node] = child
            self.pull(node)
            child, node = node, self.parent[node]
        self.splay(x)

    def root_at(self, x):
        self.access(x)
        self.flip(x)

    def link(self, u, v):
        self.root_at(u)
        self.parent[u] = v

    def cut(self, u, v):
        self.root_at(u)
        self.access(v)
        self.left[v] = self.parent[u] = 0
        self.pull(v)

    def path(self, u, v):
        self.root_at(u)
        self.access(v)

def sol(values, ops):
    tree = LinkCut(values)
    answers = []
    for kind, a, b in ops:
        u = a + 1
        if kind == 0:
            tree.link(u, b + 1)
        elif kind == 1:
            tree.cut(u, b + 1)
        elif kind == 2:
            tree.access(u)
            tree.value[u] = b
            tree.pull(u)
        else:
            tree.path(u, b + 1)
            answers.append(tree.total[b + 1])
    return answers

