def sol(n, edges):
    nodes = LinkCut([-1] * n + [w for _, _, w in edges])
    parent = list(range(n))
    size = [1] * n
    def find(x):
        while x != parent[x]:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    count, cost, answers = n, 0, []
    for i, (u, v, w) in enumerate(edges):
        edge = n + i + 1
        a, b = find(u), find(v)
        install = a != b
        if install:
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]
            count -= 1
        elif u != v:
            nodes.path(u + 1, v + 1)
            old = nodes.heaviest[v + 1]
            if nodes.value[old] > w:
                s, t, old_weight = edges[old - n - 1]
                nodes.cut(s + 1, old)
                nodes.cut(t + 1, old)
                cost -= old_weight
                install = True
        if install:
            nodes.link(u + 1, edge)
            nodes.link(v + 1, edge)
            cost += w
        answers.append(cost if count == 1 else -1)
    return answers

def sol(n, ops):
    q = len(ops)
    periods = [[] for _ in range(4 * q)]
    def store(node, lo, hi, a, b, edge):
        if b <= lo or hi <= a:
            return
        if a <= lo and hi <= b:
            periods[node].append(edge)
            return
        mid = (lo + hi) // 2
        store(2 * node, lo, mid, a, b, edge)
        store(2 * node + 1, mid, hi, a, b, edge)
    starts = {}
    for i, (kind, u, v) in enumerate(ops):
        edge = tuple(sorted((u, v)))
        if kind == 0:
            starts[edge] = i
        elif kind == 1:
            store(1, 0, q, starts.pop(edge), i, edge)
    for edge, start in starts.items():
        store(1, 0, q, start, q, edge)
    parent = list(range(n))
    size = [1] * n
    history, answers = [], []
    def find(u):
        while parent[u] != u:
            u = parent[u]
        return u
    def visit(node, lo, hi):
        checkpoint = len(history)
        for u, v in periods[node]:
            u, v = find(u), find(v)
            if u == v:
                continue
            if size[u] < size[v]:
                u, v = v, u
            history.append((u, v))
            size[u] += size[v]
            parent[v] = u
        if hi == lo + 1:
            kind, u, v = ops[lo]
            if kind == 2:
                answers.append(int(find(u) == find(v)))
        else:
            mid = (lo + hi) // 2
            visit(node * 2, lo, mid)
            visit(node * 2 + 1, mid, hi)
        while len(history) > checkpoint:
            u, v = history.pop()
            size[u] -= size[v]
            parent[v] = v
    visit(1, 0, q)
    return answers

def sol(values, parents, queries):
    ordered = sorted(set(values))
    rank = {v: i for i, v in enumerate(ordered)}
    n, width = len(values), len(ordered)
    left, right, count = [0], [0], [0]
    def add(old, lo, hi, pos):
        node = len(left)
        left.append(left[old])
        right.append(right[old])
        count.append(count[old] + 1)
        if hi - lo > 1:
            mid = (lo + hi) // 2
            if pos < mid:
                left[node] = add(left[old], lo, mid, pos)
            else:
                right[node] = add(right[old], mid, hi, pos)
        return node
    up = [[0] + list(parents)]
    for _ in range(1, n.bit_length()):
        prev = up[-1]
        up.append([prev[prev[v]] for v in range(n)])
    version, depth = [], [0] * n
    for v, value in enumerate(values):
        p = up[0][v]
        version.append(add(version[p] if v else 0, 0, width, rank[value]))
        if v:
            depth[v] = depth[p] + 1
    def lca(a, b):
        if depth[a] < depth[b]:
            a, b = b, a
        diff = depth[a] - depth[b]
        for i, level in enumerate(up):
            if diff >> i & 1:
                a = level[a]
        if a == b:
            return a
        for level in reversed(up):
            if level[a] != level[b]:
                a, b = level[a], level[b]
        return up[0][a]
    ans = []
    for u, v, k in queries:
        p = lca(u, v)
        a, b, c, d = version[u], version[v], version[p], version[up[0][p]] if p else 0
        lo, hi = 0, width
        while hi - lo > 1:
            mid = (lo + hi) // 2
            smaller = count[left[a]] + count[left[b]] - count[left[c]] - count[left[d]]
            if smaller >= k:
                a, b, c, d = left[a], left[b], left[c], left[d]
                hi = mid
            else:
                a, b, c, d = right[a], right[b], right[c], right[d]
                k -= smaller
                lo = mid
        ans.append(ordered[lo])
    return ans

def sol(parents, k):
    n = len(parents) + 1
    adj = [[] for _ in range(n)]
    for v, p in enumerate(parents, 1):
        adj[v].append(p)
        adj[p].append(v)
    removed, size, parent = [False]*n, [0]*n, [-1]*n
    components, answer = [0], 0
    while components:
        start = components.pop()
        order = [start]
        parent[start] = -1
        for v in order:
            for w in adj[v]:
                if w != parent[v] and not removed[w]:
                    order.append(w)
                    parent[w] = v
        middle = start
        for v in reversed(order):
            size[v] = 1
            largest = 0
            for w in adj[v]:
                if not removed[w] and parent[w] == v:
                    size[v] += size[w]
                    largest = max(largest, size[w])
            if 2 * max(largest, len(order) - size[v]) <= len(order):
                middle = v
        removed[middle] = True
        frequency = {0: 1}
        for w in adj[middle]:
            if removed[w]:
                continue
            components.append(w)
            stack, distances = [(w, middle, 1)], []
            while stack:
                v, p, dist = stack.pop()
                if dist > k:
                    continue
                answer += frequency.get(k - dist, 0)
                distances.append(dist)
                stack.extend((u, v, dist + 1) for u in adj[v] if u != p and not removed[u])
            for dist in distances:
                frequency[dist] = frequency.get(dist, 0) + 1
    return answer

def sol(n, edges):
    from collections import deque
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    mate = [-1]*n
    def augment(start):
        prev, base, seen = [-1]*n, list(range(n)), [False]*n
        seen[start] = True
        queue = deque([start])
        def common(a,b):
            path = set()
            while True:
                a = base[a]
                path.add(a)
                if mate[a] < 0:
                    break
                a = prev[mate[a]]
            while base[b] not in path:
                b = prev[mate[base[b]]]
            return base[b]
        def mark(v, root, child, inside):
            while base[v] != root:
                inside.add(base[v]); inside.add(base[mate[v]])
                prev[v], child = child, mate[v]
                v = prev[child]
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if base[u] == base[v] or mate[u] == v:
                    continue
                if v == start or (mate[v] >= 0 and prev[mate[v]] >= 0):
                    center = common(u,v)
                    inside = set()
                    mark(u,center,v,inside)
                    mark(v,center,u,inside)
                    for w in range(n):
                        if base[w] in inside:
                            base[w] = center
                            if not seen[w]:
                                seen[w] = True
                                queue.append(w)
                elif prev[v] < 0:
                    prev[v] = u
                    if mate[v] < 0:
                        while v >= 0:
                            p = prev[v]
                            nxt = mate[p] if p >= 0 else -1
                            mate[v] = p
                            if p >= 0:
                                mate[p] = v
                            v = nxt
                        return True
                    seen[mate[v]] = True
                    queue.append(mate[v])
        return False
    return sum(augment(i) for i in range(n) if mate[i] < 0)

class Residual:
    def __init__(self,n):
        self.adj = [[] for _ in range(n)]

    def arc(self,u,v,c,back=0):
        a,b = self.adj[u],self.adj[v]
        a.append([v,c,len(b)])
        b.append([u,back,len(a)-1])

    def reachable(self,s):
        seen = {s}
        stack = [s]
        while stack:
            for v,c,_ in self.adj[stack.pop()]:
                if c and v not in seen:
                    seen.add(v)
                    stack.append(v)
        return seen

    def flow(self,s,t):
        total = 0
        while True:
            depth = [-1]*len(self.adj)
            order = [s]
            depth[s] = 0
            for u in order:
                for v,c,_ in self.adj[u]:
                    if c and depth[v] < 0:
                        depth[v] = depth[u]+1
                        order.append(v)
            if depth[t] < 0:
                return total
            current = [0]*len(depth)
            def push(u,limit):
                if u == t:
                    return limit
                while current[u] < len(self.adj[u]):
                    e = self.adj[u][current[u]]
                    v,cap,back = e
                    if cap and depth[v] == depth[u]+1:
                        sent = push(v,min(limit,cap))
                        if sent:
                            e[1] -= sent
                            self.adj[v][back][1] += sent
                            return sent
                    current[u] += 1
                return 0
            while True:
                sent = push(s,10**18)
                if not sent:
                    break
                total += sent

def sol(n,edges,queries):
    parents, cost = [0]*n, [0]*n
    for s in range(1,n):
        t = parents[s]
        g = Residual(n)
        for u,v,c in edges:
            g.arc(u,v,c,c)
        value = g.flow(s,t)
        side = g.reachable(s)
        for u in range(s+1,n):
            if parents[u] == t and u in side:
                parents[u] = s
        if parents[t] in side:
            parents[s],parents[t] = parents[t],s
            cost[s],cost[t] = cost[t],value
        else:
            cost[s] = value
    tree = [[] for _ in range(n)]
    for u in range(1,n):
        p = parents[u]
        tree[p].append((u,cost[u]))
        tree[u].append((p,cost[u]))
    result = []
    for s,t in queries:
        stack = [(s,-1,10**18)]
        while stack:
            v,p,smallest = stack.pop()
            if v == t:
                result.append(smallest)
                break
            stack.extend((w,v,min(smallest,c)) for w,c in tree[v] if w!=p)
    return result

