                        row[mask] = (row[mask]+row[mask-step])%prime
        return table
    f,g = ranked(a),ranked(b)
    answer = [0]*length
    for degree in range(k+1):
        h = [0]*length
        for i in range(degree+1):
            for mask,(x,y) in enumerate(zip(f[i],g[degree-i])):
                h[mask] = (h[mask]+x*y)%prime
        for bit in range(k):
            step = 1<<bit
            for lo in range(step,length,step*2):
                for mask in range(lo,lo+step):
                    h[mask] = (h[mask]-h[mask-step])%prime
        for mask,x in enumerate(h):
            if mask.bit_count()==degree:
                answer[mask] = x
    return answer

def sol(points):
    # 좌표가 모두 같은 점들을 묶어 같은 좌표의 양방향 지배를 별도로 복원한다.
    groups = {}
    for i,key in enumerate(map(tuple,points)):
        groups.setdefault(key,[]).append(i)
    ordered = sorted(groups)
    zrank = {z:i+1 for i,z in enumerate(sorted({z for _,_,z in ordered}))}
    size = [len(groups[key]) for key in ordered]
    count = [v-1 for v in size]
    bit = [0]*(len(zrank)+1)
    def update(i,v):
        while i<len(bit):
            bit[i]+=v
            i+=i&-i
    def prefix(i):
        total=0
        while i:
            total+=bit[i]
            i-=i&-i
        return total
    def cdq(lo,hi):
        if hi-lo<2:
            return
        mid=(lo+hi)//2
        cdq(lo,mid)
        cdq(mid,hi)
        left=sorted(range(lo,mid),key=lambda i:ordered[i][1])
        right=sorted(range(mid,hi),key=lambda i:ordered[i][1])
        end=0
        for j in right:
            while end<len(left) and ordered[left[end]][1]<=ordered[j][1]:
                i=left[end]
                update(zrank[ordered[i][2]],size[i])
                end+=1
            count[j]+=prefix(zrank[ordered[j][2]])
        for i in left[:end]:
            update(zrank[ordered[i][2]],-size[i])
    cdq(0,len(ordered))
    ans=[0]*len(points)
    for key,total in zip(ordered,count):
        for i in groups[key]:
            ans[i]=total
    return ans

class LineVersions:
    """정수 x 구간의 최소 직선. 튜플을 공유해 이전 버전을 보존한다."""
    def __init__(self,left,right):
        self.left,self.right=left,right

    def insert(self,node,line,lo=None,hi=None):
        if lo is None:
            lo,hi=self.left,self.right
        if node is None:
            return line,None,None
        best,lchild,rchild=node
        mid=(lo+hi)//2
        def value(f,x):
            return f[0]*x+f[1]
        if value(line,mid)<value(best,mid):
            best,line=line,best
        if lo<hi:
            if value(line,lo)<value(best,lo):
                lchild=self.insert(lchild,line,lo,mid)
            elif value(line,hi)<value(best,hi):
                rchild=self.insert(rchild,line,mid+1,hi)
        return best,lchild,rchild

    def minimum(self,node,x):
        value=float("inf")
        lo,hi=self.left,self.right
        while node is not None:
            (m,b),left,right=node
            value=min(value,m*x+b)
            if lo==hi:
                break
            mid=(lo+hi)//2
            if x<=mid:
                node,hi=left,mid
            else:
                node,lo=right,mid+1
        return value

def sol(ops):
