def sol(rects):
    if not rects:
        return 0
    ys=sorted({y for x1,y1,x2,y2 in rects for y in (y1,y2)})
    index={y:i for i,y in enumerate(ys)}
    events=sorted((x,delta,index[y1],index[y2]) for x1,y1,x2,y2 in rects
                  for x,delta in ((x1,1),(x2,-1)))
    cover=[0]*(4*len(ys))
    length=[0]*len(cover)
    def adjust(node,lo,hi,a,b,delta):
        if hi<=a or b<=lo:
            return
        if a<=lo and hi<=b:
            cover[node]+=delta
        else:
            mid=(lo+hi)//2
            adjust(2*node,lo,mid,a,b,delta)
            adjust(2*node+1,mid,hi,a,b,delta)
        if cover[node]:
            length[node]=ys[hi]-ys[lo]
        elif hi-lo==1:
            length[node]=0
        else:
            length[node]=length[2*node]+length[2*node+1]
    ans,prev=0,events[0][0]
    for x,delta,a,b in events:
        ans+=(x-prev)*length[1]
        adjust(1,0,len(ys)-1,a,b,delta)
        prev=x
    return ans

def sol(patterns,ops):
    go=[[-1]*26]
    ends=[]
    for word in patterns:
        u=0
        for char in word:
            c=ord(char)-97
            if go[u][c]<0:
                go[u][c]=len(go)
                go.append([-1]*26)
            u=go[u][c]
        ends.append(u)
    fail=[0]*len(go)
    bfs=[]
    for c,v in enumerate(go[0]):
        if v<0:
            go[0][c]=0
        else:
            bfs.append(v)
    for u in bfs:
        for c,v in enumerate(go[u]):
            if v<0:
                go[u][c]=go[fail[u]][c]
            else:
                fail[v]=go[fail[u]][c]
                bfs.append(v)
    children=[[] for _ in go]
    for v in bfs:
        children[fail[v]].append(v)
    start,end=[0]*len(go),[0]*len(go)
    tick=0
    stack=[(0,False)]
    while stack:
        v,exit_node=stack.pop()
        if exit_node:
            end[v]=tick
        else:
            tick+=1
            start[v]=tick
            stack.append((v,True))
            stack.extend((w,False) for w in children[v])
    bit=[0]*(len(go)+2)
    def update(i,delta):
        while i<len(bit):
            bit[i]+=delta
            i+=i&-i
    active=[False]*len(patterns)
    state,ans=0,[]
    for kind,x in ops:
        if kind==2:
            state=go[state][x]
            hits=0
            i=start[state]
            while i:
                hits+=bit[i]
                i-=i&-i
            ans.append(hits)
        elif active[x]!=(kind==0):
            active[x]=kind==0
            delta=1 if active[x] else -1
            update(start[ends[x]],delta)
            update(end[ends[x]]+1,-delta)
    return ans

